package android.widget;import android.content.Context;import android.view.*;public class TextView extends View {public CharSequence text="";public float size=14;public TextView(Context c){super(c);}public void setText(CharSequence s){text=s;}public void setTextSize(float s){size=s;}public void setTextColor(int c){}public void setTypeface(Object t,int style){}public void setGravity(int g){}@Override public void measure(int w,int h){int width=Math.max(1,MeasureSpec.getSize(w));int rows=Math.max(1,(int)Math.ceil(text.length()*size*getResources().getDisplayMetrics().scaledDensity/width));setMeasuredDimension(width,padding+(int)(rows*size*1.4*getResources().getDisplayMetrics().scaledDensity));}}
